def hermite(keys, f, t0=None, t1=None):
    # keys: list of (frame, V3); catmull tangents; t0/t1 optional end tangents
    n=len(keys)
    for i in range(n-1):
        fa,pa=keys[i]; fb,pb=keys[i+1]
