    def tan(j):
        if j==0: return t0 if t0 is not None else (keys[1][1]-keys[0][1])*(1.0/(keys[1][0]-keys[0][0]))
        if j==n-1: return t1 if t1 is not None else (keys[-1][1]-keys[-2][1])*(1.0/(keys[-1][0]-keys[-2][0]))
        return (keys[j+1][1]-keys[j-1][1])*(1.0/(keys[j+1][0]-keys[j-1][0]))
